#[command(name = "hck")]
#[command(about = "hck is a small command-line utility similar to cut(1)", long_about = None)]
#[command(version = "hck git:23bebe8-modified")]
struct Args {
    /// Input files to parse, defaults to stdin.
    #[arg(value_name = "INPUT")]
    input: Vec<PathBuf>,

    /// Output file to write to, defaults to stdout
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Delimiter to use on input files, this is a regex by default
    #[arg(short, long, default_value = "\\s+")]
    delimiter: String,

    /// Treat the delimiter as a string literal
    #[arg(short = 'L', long)]
    delim_is_literal: bool,

    /// Use the input delimiter as the output delimiter if the input is literal and no other output delimiter has been set
    #[arg(short = 'I', long)]
    use_input_delim: bool,

    /// Delimiter string to use on outputs
    #[arg(short = 'D', long, default_value = "\t")]
    output_delimiter: String,

    /// Fields to keep in the output, ex: 1,2-,-5,2-5
    #[arg(short, long)]
    fields: Option<String>,

    /// Fields to exclude from the output
    #[arg(short, long)]
    exclude: Option<String>,

    /// Headers to exclude from the output
    #[arg(short = 'E', long)]
    exclude_header: Vec<String>,

    /// A string literal or regex to select headers
    #[arg(short = 'F', long)]
    header_field: Vec<String>,

    /// Treat the header_fields as regexs instead of string literals
    #[arg(short = 'r', long)]
    header_is_regex: bool,

    /// Support CRLF newlines
    #[arg(long)]
    crlf: bool,
}

struct FieldSelector {
    ranges: Vec<(Option<usize>, Option<usize>)>,
}

impl FieldSelector {
    fn parse(spec: &str) -> Result<Self> {
        let mut ranges = Vec::new();
        for part in spec.split(',') {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            if let Some(dash_pos) = part.find('-') {
                let start_str = &part[..dash_pos];
                let end_str = &part[dash_pos + 1..];

                let start = if start_str.is_empty() {
                    None
                } else {
                    Some(start_str.parse::<usize>()?)
                };
                let end = if end_str.is_empty() {
                    None
                } else {
                    Some(end_str.parse::<usize>()?)
                };
                ranges.push((start, end));
            } else {
                let field = part.parse::<usize>()?;
                ranges.push((Some(field), Some(field)));
            }
        }
        Ok(FieldSelector { ranges })
    }

    fn get_fields(&self, num_fields: usize) -> Vec<usize> {
        let mut fields = Vec::new();
        let mut seen = std::collections::HashSet::new();

        for (start, end) in &self.ranges {
            let start_field = start.unwrap_or(1);
            let end_field = end.unwrap_or(num_fields);

            for field in start_field..=end_field {
                if field <= num_fields && !seen.contains(&field) {
                    fields.push(field);
                    seen.insert(field);
                }
            }
        }
        fields
    }
}

fn split_line(line: &str, delimiter: &str, is_literal: bool) -> Vec<String> {
    if is_literal {
        line.split(delimiter).map(|s| s.to_string()).collect()
    } else {
        match Regex::new(delimiter) {
            Ok(re) => re.split(line).map(|s| s.to_string()).collect(),
            Err(_) => vec![line.to_string()],
        }
    }
}

fn process_line(
    line: &str,
    fields: Option<&Vec<usize>>,
    exclude: Option<&Vec<usize>>,
    output_delim: &str,
    input_delim: &str,
    is_literal: bool,
) -> String {
    let parts = split_line(line, input_delim, is_literal);
    let num_parts = parts.len();

    let mut selected_indices: Vec<usize> = if let Some(f) = fields {
        f.clone()
    } else {
        (1..=num_parts).collect()
    };

    if let Some(exc) = exclude {
        let exclude_set: std::collections::HashSet<_> = exc.iter().copied().collect();
        selected_indices.retain(|&idx| !exclude_set.contains(&idx));
    }

    let result: Vec<String> = selected_indices
        .iter()
        .filter_map(|&idx| {
            if idx > 0 && idx <= num_parts {
                Some(parts[idx - 1].clone())
            } else {
                None
            }
        })
        .collect();

    result.join(output_delim)
}

fn process_headers(
    header_line: &str,
    input_delim: &str,
    is_literal: bool,
    header_fields: &[String],
    exclude_headers: &[String],
    header_is_regex: bool,
) -> (Vec<usize>, String) {
    let parts = split_line(header_line, input_delim, is_literal);
    let num_parts = parts.len();

    let mut selected_indices: Vec<usize> = Vec::new();

    if !header_fields.is_empty() {
        // When using header fields, include only matching headers
        for header_spec in header_fields {
            if header_is_regex {
                if let Ok(re) = Regex::new(header_spec) {
                    for (i, part) in parts.iter().enumerate() {
                        if re.is_match(part) && !selected_indices.contains(&(i + 1)) {
                            selected_indices.push(i + 1);
                        }
                    }
                }
            } else {
                for (i, part) in parts.iter().enumerate() {
                    if part == header_spec && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            }
        }
    } else {
        // No header fields specified, include all except excluded ones
        selected_indices = (1..=num_parts).collect();
    }

    // Apply exclude filters
    for exclude_spec in exclude_headers {
        if header_is_regex {
            if let Ok(re) = Regex::new(exclude_spec) {
                selected_indices.retain(|&idx| {
                    if idx > 0 && idx <= num_parts {
                        !re.is_match(&parts[idx - 1])
                    } else {
                        true
                    }
                });
            }
        } else {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    &parts[idx - 1] != exclude_spec
                } else {
                    true
                }
            });
        }
    }

    let result: Vec<String> = selected_indices
        .iter()
        .filter_map(|&idx| {
            if idx > 0 && idx <= num_parts {
                Some(parts[idx - 1].clone())
            } else {
                None
            }
        })
        .collect();

    (selected_indices, result.join("\t"))
}

fn main() -> Result<()> {
