    };

    let inputs: Vec<Box<dyn BufRead>> = if args.input.is_empty() {
        vec![Box::new(BufReader::new(io::stdin()))]
    } else {
        args.input
            .iter()
            .map(|p| -> Result<Box<dyn BufRead>> {
                Ok(Box::new(BufReader::new(File::open(p)?)))
            })
            .collect::<Result<Vec<_>>>()?
    };

    for reader in inputs {
        let mut lines = reader.lines();
        let mut is_first_line = true;
        let mut selected_header_fields: Option<Vec<usize>> = None;

        for line in lines {
            let line = line?;

            // Skip empty lines at end
            if line.is_empty() && is_first_line {
                continue;
            }

            if is_first_line && (!args.header_field.is_empty() || !args.exclude_header.is_empty()) {
