fn process_headers(
    header_line: &str,
    input_delim: &str,
    is_literal: bool,
    header_fields: &[String],
    exclude_headers: &[String],
    header_is_regex: bool,
) -> (Vec<usize>, String) {
    let parts = split_line(header_line, input_delim, is_literal);
    let num_parts = parts.len();

    let mut selected_indices: Vec<usize> = Vec::new();

    if !header_fields.is_empty() {
        // When using header fields, include only matching headers
        for header_spec in header_fields {
            if header_is_regex {
                for (i, part) in parts.iter().enumerate() {
                    if matches_regex(header_spec, part) && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            } else {
                for (i, part) in parts.iter().enumerate() {
                    if part == header_spec && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            }
        }
    } else {
        // No header fields specified, include all except excluded ones
        selected_indices = (1..=num_parts).collect();
    }

    // Apply exclude filters
    for exclude_spec in exclude_headers {
        if header_is_regex {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    !matches_regex(exclude_spec, &parts[idx - 1])
                } else {
                    true
                }
            });
        } else {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    &parts[idx - 1] != exclude_spec
                } else {
                    true
                }
            });
        }
    }

    let result: Vec<String> = selected_indices
        .iter()
        .filter_map(|&idx| {
            if idx > 0 && idx <= num_parts {
                Some(parts[idx - 1].clone())
            } else {
                None
            }
        })
        .collect();

    (selected_indices, result.join("\t"))
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [INPUT]...");
    println!();
    println!("Arguments:");
    println!("  [INPUT]...  Input files to parse, defaults to stdin.");
    println!();
    println!("Options:");
    println!("  -o, --output <OUTPUT>              Output file to write to");
    println!("  -d, --delimiter <DELIMITER>        Delimiter to use on input files");
    println!("  -L, --delim-is-literal             Treat the delimiter as a string literal");
    println!("  -I, --use-input-delim              Use the input delimiter as the output delimiter");
    println!("  -D, --output-delimiter <DELIM>     Delimiter string to use on outputs");
    println!("  -f, --fields <FIELDS>              Fields to keep in the output");
    println!("  -e, --exclude <EXCLUDE>            Fields to exclude from the output");
    println!("  -E, --exclude-header <EXCLUDE>     Headers to exclude from the output");
    println!("  -F, --header-field <HEADER>        A string literal or regex to select headers");
    println!("  -r, --header-is-regex              Treat the header_fields as regexs");
    println!("  -h, --help                         Print help");
    println!("  -V, --version                      Print version");
}
