impl FieldSelector {
    fn parse(spec: &str) -> Result<Self, String> {
        let mut ranges = Vec::new();
        for part in spec.split(',') {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            if let Some(dash_pos) = part.find('-') {
                let start_str = &part[..dash_pos];
                let end_str = &part[dash_pos + 1..];

                let start = if start_str.is_empty() {
                    None
                } else {
                    Some(start_str.parse::<usize>()
                        .map_err(|_| format!("Invalid field number: {}", start_str))?)
                };
                let end = if end_str.is_empty() {
                    None
                } else {
                    Some(end_str.parse::<usize>()
                        .map_err(|_| format!("Invalid field number: {}", end_str))?)
                };
                ranges.push((start, end));
            } else {
                let field = part.parse::<usize>()
                    .map_err(|_| format!("Invalid field number: {}", part))?;
                ranges.push((Some(field), Some(field)));
            }
        }
        Ok(FieldSelector { ranges })
    }

    fn get_fields(&self, num_fields: usize) -> Vec<usize> {
        let mut fields = Vec::new();
