fn main() {
    let args: Vec<String> = env::args().collect();

    // Parse arguments
    let mut input_files: Vec<PathBuf> = Vec::new();
    let mut output_file: Option<PathBuf> = None;
    let mut delimiter = "\\s+".to_string();
    let mut delim_is_literal = false;
    let mut use_input_delim = false;
    let mut output_delimiter = "\t".to_string();
    let mut fields: Option<String> = None;
    let mut exclude: Option<String> = None;
    let mut exclude_headers: Vec<String> = Vec::new();
    let mut header_fields: Vec<String> = Vec::new();
    let mut header_is_regex = false;
    let mut show_version = false;
    let mut show_help = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "--version" | "-V" => {
                show_version = true;
                break;
            }
            "-h" | "--help" => {
                show_help = true;
                break;
            }
            "-d" | "--delimiter" => {
                i += 1;
                if i < args.len() {
                    delimiter = args[i].clone();
                } else {
                    eprintln!("Error: -d requires a value");
                    std::process::exit(1);
                }
            }
            "-L" | "--delim-is-literal" => {
                delim_is_literal = true;
            }
            "-I" | "--use-input-delim" => {
                use_input_delim = true;
            }
            "-D" | "--output-delimiter" => {
                i += 1;
                if i < args.len() {
                    output_delimiter = args[i].clone();
                } else {
                    eprintln!("Error: -D requires a value");
                    std::process::exit(1);
                }
            }
            "-f" | "--fields" => {
                i += 1;
                if i < args.len() {
                    fields = Some(args[i].clone());
                } else {
                    eprintln!("Error: -f requires a value");
                    std::process::exit(1);
                }
            }
            "-e" | "--exclude" => {
                i += 1;
                if i < args.len() {
                    exclude = Some(args[i].clone());
                } else {
                    eprintln!("Error: -e requires a value");
                    std::process::exit(1);
                }
            }
            "-E" | "--exclude-header" => {
                i += 1;
                if i < args.len() {
                    exclude_headers.push(args[i].clone());
                } else {
                    eprintln!("Error: -E requires a value");
                    std::process::exit(1);
                }
            }
            "-F" | "--header-field" => {
                i += 1;
                if i < args.len() {
                    header_fields.push(args[i].clone());
                } else {
                    eprintln!("Error: -F requires a value");
                    std::process::exit(1);
                }
            }
            "-r" | "--header-is-regex" => {
                header_is_regex = true;
            }
            "-o" | "--output" => {
                i += 1;
                if i < args.len() {
                    output_file = Some(PathBuf::from(&args[i]));
                } else {
                    eprintln!("Error: -o requires a value");
                    std::process::exit(1);
                }
            }
            s if s.starts_with('-') => {
                // Unknown option
                eprintln!("Unknown option: {}", s);
                std::process::exit(1);
            }
            _ => {
                input_files.push(PathBuf::from(arg));
            }
        }
        i += 1;
    }

    if show_version {
        println!("hck git:23bebe8-modified");
        return;
    }

    if show_help {
        print_help();
        return;
    }

    // Determine output delimiter
    let final_output_delim = if use_input_delim && delim_is_literal && output_delimiter == "\t" {
        delimiter.clone()
    } else {
        output_delimiter.clone()
    };

    // Parse field selectors
    let mut field_selector: Option<Vec<usize>> = None;
    let mut exclude_fields: Option<Vec<usize>> = None;

    if let Some(f) = fields {
        match FieldSelector::parse(&f) {
            Ok(selector) => {
                field_selector = Some(selector.get_fields(usize::MAX));
            }
            Err(e) => {
                eprintln!("Error parsing fields: {}", e);
                std::process::exit(1);
            }
        }
    }

    if let Some(e) = exclude {
        match FieldSelector::parse(&e) {
            Ok(selector) => {
                exclude_fields = Some(selector.get_fields(usize::MAX));
            }
            Err(e) => {
                eprintln!("Error parsing exclude: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Prepare output
    let mut output: Box<dyn Write> = if let Some(path) = output_file {
        match File::create(path) {
            Ok(f) => Box::new(f),
            Err(e) => {
                eprintln!("Error opening output file: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        Box::new(io::stdout())
    };

    // Prepare input readers
    let readers: Vec<Box<dyn BufRead>> = if input_files.is_empty() {
        vec![Box::new(BufReader::new(io::stdin()))]
    } else {
        input_files
            .iter()
            .filter_map(|p| {
                match File::open(p) {
                    Ok(f) => Some(Box::new(BufReader::new(f)) as Box<dyn BufRead>),
                    Err(e) => {
                        eprintln!("Error opening file {:?}: {}", p, e);
                        None
                    }
                }
            })
            .collect()
    };

    // Process input
    for reader in readers {
        let mut is_first_line = true;
        let mut selected_header_fields: Option<Vec<usize>> = None;

        for line in reader.lines() {
            match line {
                Ok(line) => {
                    if is_first_line && (!header_fields.is_empty() || !exclude_headers.is_empty()) {
                        // Process header line
                        let (indices, _header_output) = process_headers(
                            &line,
                            &delimiter,
                            delim_is_literal,
                            &header_fields,
                            &exclude_headers,
                            header_is_regex,
                        );
                        selected_header_fields = Some(indices.clone());

                        // Output the header
                        let parts = split_line(&line, &delimiter, delim_is_literal);
                        let header_output: Vec<String> = indices
                            .iter()
                            .filter_map(|&idx| {
                                if idx > 0 && idx <= parts.len() {
                                    Some(parts[idx - 1].clone())
                                } else {
                                    None
                                }
                            })
                            .collect();
                        let _ = writeln!(output, "{}", header_output.join("\t"));
                        is_first_line = false;
                    } else if is_first_line {
                        is_first_line = false;
                        let parts = split_line(&line, &delimiter, delim_is_literal);

                        // Output first line
                        if let Some(ref selector) = field_selector {
                            let fields_to_use: Vec<usize> = selector
                                .iter()
                                .filter(|&&f| f <= parts.len())
                                .copied()
                                .collect();

                            if !fields_to_use.is_empty() {
                                let result: Vec<String> = fields_to_use
                                    .iter()
                                    .filter_map(|&idx| {
                                        if idx > 0 && idx <= parts.len() {
                                            Some(parts[idx - 1].clone())
                                        } else {
                                            None
                                        }
                                    })
                                    .collect();
                                let _ = writeln!(output, "{}", result.join(&final_output_delim));
                            }
                        } else {
                            // No field selector, use exclude only
                            let result: Vec<String> = parts
                                .into_iter()
                                .enumerate()
                                .filter_map(|(i, part)| {
                                    if let Some(ref exc) = exclude_fields {
                                        if !exc.contains(&(i + 1)) {
                                            Some(part)
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(part)
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        }
                    } else {
                        // Process data lines
                        if let Some(ref selected_indices) = selected_header_fields {
                            let parts = split_line(&line, &delimiter, delim_is_literal);
                            let result: Vec<String> = selected_indices
                                .iter()
                                .filter_map(|&idx| {
                                    if idx > 0 && idx <= parts.len() {
                                        Some(parts[idx - 1].clone())
                                    } else {
                                        None
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join("\t"));
                        } else if let Some(ref selector) = field_selector {
                            let parts = split_line(&line, &delimiter, delim_is_literal);
                            let fields_to_use: Vec<usize> = selector
                                .iter()
                                .filter(|&&f| f <= parts.len())
                                .copied()
                                .collect();

                            if !fields_to_use.is_empty() {
                                let result: Vec<String> = fields_to_use
                                    .iter()
                                    .filter_map(|&idx| {
                                        if idx > 0 && idx <= parts.len() {
                                            Some(parts[idx - 1].clone())
                                        } else {
                                            None
                                        }
                                    })
                                    .collect();
                                let _ = writeln!(output, "{}", result.join(&final_output_delim));
                            }
                        } else {
                            let parts = split_line(&line, &delimiter, delim_is_literal);
                            let result: Vec<String> = parts
                                .into_iter()
                                .enumerate()
                                .filter_map(|(i, part)| {
                                    if let Some(ref exc) = exclude_fields {
                                        if !exc.contains(&(i + 1)) {
                                            Some(part)
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(part)
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error reading line: {}", e);
                }
            }
        }
    }
}

fn process_headers(
    header_line: &str,
    input_delim: &str,
    is_literal: bool,
    header_fields: &[String],
    exclude_headers: &[String],
    header_is_regex: bool,
) -> (Vec<usize>, String) {
    let parts = split_line(header_line, input_delim, is_literal);
    let num_parts = parts.len();

    let mut selected_indices: Vec<usize> = Vec::new();

    if !header_fields.is_empty() {
        // When using header fields, include only matching headers
        for header_spec in header_fields {
            if header_is_regex {
                for (i, part) in parts.iter().enumerate() {
                    if matches_regex(header_spec, part) && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            } else {
                for (i, part) in parts.iter().enumerate() {
                    if part == header_spec && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            }
        }
    } else {
        // No header fields specified, include all except excluded ones
        selected_indices = (1..=num_parts).collect();
    }

    // Apply exclude filters
    for exclude_spec in exclude_headers {
        if header_is_regex {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    !matches_regex(exclude_spec, &parts[idx - 1])
                } else {
                    true
                }
            });
        } else {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    &parts[idx - 1] != exclude_spec
                } else {
                    true
                }
            });
        }
    }

    let result: Vec<String> = selected_indices
        .iter()
        .filter_map(|&idx| {
            if idx > 0 && idx <= num_parts {
                Some(parts[idx - 1].clone())
            } else {
                None
            }
        })
        .collect();

    (selected_indices, result.join("\t"))
}

