            std::process::exit(1);
        }
    };

    // Determine output delimiter
    let final_output_delim = if args.use_input_delim && args.delim_is_literal && args.output_delimiter == "\t" {
        args.delimiter.clone()
    } else {
        args.output_delimiter.clone()
    };

    // Parse field selectors
    let mut field_selector: Option<Vec<usize>> = None;
    let mut exclude_fields: Option<Vec<usize>> = None;

    if let Some(f) = &args.fields {
        match FieldSelector::parse(f) {
            Ok(selector) => {
                field_selector = Some(selector.get_fields(usize::MAX));
            }
            Err(e) => {
                eprintln!("Error parsing fields: {}", e);
                std::process::exit(1);
            }
        }
    }

    if let Some(e) = &args.exclude {
        match FieldSelector::parse(e) {
            Ok(selector) => {
                exclude_fields = Some(selector.get_fields(usize::MAX));
            }
            Err(e) => {
                eprintln!("Error parsing exclude: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Prepare output
    let mut output: Box<dyn Write> = if let Some(path) = args.output_file {
        match File::create(path) {
            Ok(f) => Box::new(f),
            Err(e) => {
                eprintln!("Error opening output file: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        Box::new(io::stdout())
    };

    // Prepare input readers
    let readers: Vec<Box<dyn BufRead>> = if args.input_files.is_empty() {
        vec![Box::new(BufReader::new(io::stdin()))]
    } else {
        args.input_files
            .iter()
            .filter_map(|p| {
                match File::open(p) {
                    Ok(f) => Some(Box::new(BufReader::new(f)) as Box<dyn BufRead>),
                    Err(e) => {
                        eprintln!("Error opening file {:?}: {}", p, e);
                        None
                    }
                }
            })
            .collect()
    };

    // Process input
    for reader in readers {
        let mut is_first_line = true;
        let mut selected_header_fields: Option<Vec<usize>> = None;

        for line in reader.lines() {
            match line {
                Ok(line) => {
                    if is_first_line && (!args.header_fields.is_empty() || !args.exclude_headers.is_empty()) {
                        // Process header line
                        let (indices, _header_output) = process_headers(
                            &line,
                            &args.delimiter,
                            args.delim_is_literal,
                            &args.header_fields,
                            &args.exclude_headers,
                            args.header_is_regex,
                        );
                        selected_header_fields = Some(indices.clone());

