                        let parts = split_line(&line, &args.delimiter, args.delim_is_literal);
                        let header_output: Vec<String> = indices
                            .iter()
                            .filter_map(|&idx| {
                                if idx > 0 && idx <= parts.len() {
                                    Some(parts[idx - 1].clone())
                                } else {
                                    None
                                }
                            })
                            .collect();
                        let _ = writeln!(output, "{}", header_output.join("\t"));
                        is_first_line = false;
                    } else if is_first_line {
                        is_first_line = false;
                        let parts = split_line(&line, &args.delimiter, args.delim_is_literal);

                        // Output first line
                        if let Some(ref selector) = field_selector {
                            let fields_to_use: Vec<usize> = selector
                                .iter()
                                .filter(|&&f| f <= parts.len())
                                .copied()
                                .collect();

