                            }
                            break;
                        }
                    }
                    'F' => {
                        if j + 1 < arg.len() {
                            header_fields.push(arg[j + 1..].to_string());
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                header_fields.push(args[i].clone());
                            } else {
                                return Err("Error: -F requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'r' => {
                        header_is_regex = true;
                        j += 1;
                    }
                    'o' => {
                        if j + 1 < arg.len() {
                            output_file = Some(PathBuf::from(&arg[j + 1..]));
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                output_file = Some(PathBuf::from(&args[i]));
                            } else {
                                return Err("Error: -o requires a value".to_string());
                            }
                            break;
                        }
                    }
                    _ => {
                        return Err(format!("Unknown option: -{}", c));
                    }
                }
            }
        } else if arg.starts_with('-') {
            return Err(format!("Unknown option: {}", arg));
        } else {
            input_files.push(PathBuf::from(arg));
        }
        i += 1;
    }

    Ok(Args {
        input_files,
        output_file,
        delimiter,
        delim_is_literal,
        use_input_delim,
        output_delimiter,
        fields,
        exclude,
        exclude_headers,
        header_fields,
        header_is_regex,
    })
