                                        if idx > 0 && idx <= parts.len() {
                                            Some(parts[idx - 1].clone())
                                        } else {
                                            None
                                        }
                                    })
                                    .collect();
                                let _ = writeln!(output, "{}", result.join(&final_output_delim));
                            }
                        } else {
                            // No field selector, use exclude only
                            let result: Vec<String> = parts
                                .into_iter()
                                .enumerate()
                                .filter_map(|(i, part)| {
                                    if let Some(ref exc) = exclude_fields {
                                        if !exc.contains(&(i + 1)) {
                                            Some(part)
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(part)
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        }
                    } else {
                        // Process data lines
                        if let Some(ref selected_indices) = selected_header_fields {
                            let parts = split_line(&line, &args.delimiter, args.delim_is_literal);
                            let result: Vec<String> = selected_indices
                                .iter()
                                .filter_map(|&idx| {
                                    if idx > 0 && idx <= parts.len() {
                                        Some(parts[idx - 1].clone())
                                    } else {
                                        None
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join("\t"));
                        } else if let Some(ref selector) = field_selector {
                            let parts = split_line(&line, &args.delimiter, args.delim_is_literal);
                            let fields_to_use: Vec<usize> = selector
                                .iter()
                                .filter(|&&f| f <= parts.len())
                                .copied()
                                .collect();

                            if !fields_to_use.is_empty() {
                                let result: Vec<String> = fields_to_use
                                    .iter()
                                    .filter_map(|&idx| {
                                        if idx > 0 && idx <= parts.len() {
                                            Some(parts[idx - 1].clone())
                                        } else {
                                            None
                                        }
                                    })
                                    .collect();
                                let _ = writeln!(output, "{}", result.join(&final_output_delim));
                            }
                        } else {
                            let parts = split_line(&line, &args.delimiter, args.delim_is_literal);
                            let result: Vec<String> = parts
                                .into_iter()
                                .enumerate()
                                .filter_map(|(i, part)| {
                                    if let Some(ref exc) = exclude_fields {
                                        if !exc.contains(&(i + 1)) {
                                            Some(part)
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(part)
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error reading line: {}", e);
                }
            }
        }
    }
}

fn process_headers(
    header_line: &str,
    input_delim: &str,
    is_literal: bool,
    header_fields: &[String],
    exclude_headers: &[String],
    header_is_regex: bool,
) -> (Vec<usize>, String) {
    let parts = split_line(header_line, input_delim, is_literal);
    let num_parts = parts.len();

    let mut selected_indices: Vec<usize> = Vec::new();

    if !header_fields.is_empty() {
        // When using header fields, include only matching headers
        for header_spec in header_fields {
            if header_is_regex {
                for (i, part) in parts.iter().enumerate() {
                    if matches_regex(header_spec, part) && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            } else {
                for (i, part) in parts.iter().enumerate() {
                    if part == header_spec && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            }
        }
    } else {
        // No header fields specified, include all except excluded ones
        selected_indices = (1..=num_parts).collect();
    }

    // Apply exclude filters
    for exclude_spec in exclude_headers {
        if header_is_regex {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    !matches_regex(exclude_spec, &parts[idx - 1])
                } else {
                    true
                }
            });
        } else {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    &parts[idx - 1] != exclude_spec
                } else {
                    true
                }
            });
        }
    }

    let result: Vec<String> = selected_indices
        .iter()
        .filter_map(|&idx| {
            if idx > 0 && idx <= num_parts {
                Some(parts[idx - 1].clone())
            } else {
                None
            }
        })
        .collect();

    (selected_indices, result.join("\t"))
}

