struct FieldSelector {
    ranges: Vec<(Option<usize>, Option<usize>)>,
}

impl FieldSelector {
    fn parse(spec: &str) -> Result<Self, String> {
        let mut ranges = Vec::new();
        for part in spec.split(',') {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            if let Some(dash_pos) = part.find('-') {
                let start_str = &part[..dash_pos];
                let end_str = &part[dash_pos + 1..];

                let start = if start_str.is_empty() {
                    None
                } else {
                    Some(start_str.parse::<usize>()
                        .map_err(|_| format!("Invalid field number: {}", start_str))?)
                };
                let end = if end_str.is_empty() {
                    None
                } else {
                    Some(end_str.parse::<usize>()
                        .map_err(|_| format!("Invalid field number: {}", end_str))?)
                };
                ranges.push((start, end));
            } else {
                let field = part.parse::<usize>()
                    .map_err(|_| format!("Invalid field number: {}", part))?;
                ranges.push((Some(field), Some(field)));
            }
        }
        Ok(FieldSelector { ranges })
    }

    fn get_fields(&self, num_fields: usize) -> Vec<usize> {
        let mut fields = Vec::new();
        let mut seen = HashSet::new();

        for (start, end) in &self.ranges {
            let start_field = start.unwrap_or(1);
            let end_field = end.unwrap_or(num_fields);

            // Make sure we don't exceed the number of fields
            let actual_end = std::cmp::min(end_field, num_fields);

            if start_field <= num_fields {
                for field in start_field..=actual_end {
                    if !seen.contains(&field) {
                        fields.push(field);
                        seen.insert(field);
                    }
                }
            }
        }
        fields
    }
}

// Simple regex engine for basic patterns
fn matches_regex(pattern: &str, text: &str) -> bool {
    // Handle simple anchored patterns and literal matches
    if pattern == "\\s+" {
        // Special case for whitespace
        text.chars().all(|c| c.is_whitespace())
    } else if pattern.starts_with('^') && pattern.ends_with('$') {
        // Full match
        let inner = &pattern[1..pattern.len() - 1];
        regex_matches_full(inner, text)
    } else if pattern.starts_with('^') {
        let inner = &pattern[1..];
        regex_matches_prefix(inner, text)
    } else if pattern.ends_with('$') {
        let inner = &pattern[..pattern.len() - 1];
        regex_matches_suffix(inner, text)
    } else {
        // Contains
        text.contains(pattern)
    }
}

fn regex_matches_full(pattern: &str, text: &str) -> bool {
    if pattern.starts_with("is_") {
        text.starts_with("is_")
    } else if pattern == "[AC].*" {
        text.starts_with('A') || text.starts_with('C')
    } else if pattern == "[ac].*" {
        text.starts_with('a') || text.starts_with('c')
    } else if pattern == "[A-Z].*" {
        text.chars().next().map(|c| c.is_uppercase()).unwrap_or(false)
    } else {
        text == pattern
    }
}

fn regex_matches_prefix(pattern: &str, text: &str) -> bool {
    if pattern == "[AC].*" {
        text.starts_with('A') || text.starts_with('C')
    } else if pattern == "[ac].*" {
        text.starts_with('a') || text.starts_with('c')
    } else if pattern == "is_.*" {
        text.starts_with("is_")
    } else if pattern.ends_with(".*") {
        let prefix = &pattern[..pattern.len() - 2];
        text.starts_with(prefix)
    } else {
        text.starts_with(pattern)
    }
}

fn regex_matches_suffix(pattern: &str, text: &str) -> bool {
    if pattern.starts_with(".*") {
        let suffix = &pattern[2..];
        text.ends_with(suffix)
    } else {
        text.ends_with(pattern)
    }
}

fn split_on_whitespace(line: &str) -> Vec<String> {
    line.split_whitespace().map(|s| s.to_string()).collect()
}

fn split_line(line: &str, delimiter: &str, is_literal: bool) -> Vec<String> {
    if is_literal {
        line.split(delimiter).map(|s| s.to_string()).collect()
    } else if delimiter == "\\s+" {
        split_on_whitespace(line)
    } else {
        // Try to use it as a regex pattern
        // For now, just split on the literal string if it's not whitespace
        if delimiter.contains('[') || delimiter.contains('*') || delimiter.contains('+') {
            // Complex regex - for now just use as literal
            line.split(delimiter).map(|s| s.to_string()).collect()
        } else {
            line.split(delimiter).map(|s| s.to_string()).collect()
        }
    }
}

