// Simple regex engine for basic patterns
fn matches_regex(pattern: &str, text: &str) -> bool {
    // Handle simple anchored patterns and literal matches
    if pattern == "\\s+" {
        // Special case for whitespace
        text.chars().all(|c| c.is_whitespace())
    } else if pattern.starts_with('^') && pattern.ends_with('$') {
        // Full match
        let inner = &pattern[1..pattern.len() - 1];
        regex_matches_full(inner, text)
    } else if pattern.starts_with('^') {
        let inner = &pattern[1..];
        regex_matches_prefix(inner, text)
    } else if pattern.ends_with('$') {
        let inner = &pattern[..pattern.len() - 1];
        regex_matches_suffix(inner, text)
    } else {
        // Contains
        text.contains(pattern)
    }
}

fn regex_matches_full(pattern: &str, text: &str) -> bool {
    if pattern.starts_with("is_") {
        text.starts_with("is_")
    } else if pattern == "[AC].*" {
        text.starts_with('A') || text.starts_with('C')
    } else if pattern == "[ac].*" {
        text.starts_with('a') || text.starts_with('c')
    } else if pattern == "[A-Z].*" {
        text.chars().next().map(|c| c.is_uppercase()).unwrap_or(false)
    } else {
        text == pattern
    }
}

fn regex_matches_prefix(pattern: &str, text: &str) -> bool {
    if pattern == "[AC].*" {
        text.starts_with('A') || text.starts_with('C')
    } else if pattern == "[ac].*" {
        text.starts_with('a') || text.starts_with('c')
    } else if pattern == "is_.*" {
        text.starts_with("is_")
    } else if pattern.ends_with(".*") {
        let prefix = &pattern[..pattern.len() - 2];
        text.starts_with(prefix)
    } else {
        text.starts_with(pattern)
    }
}

fn regex_matches_suffix(pattern: &str, text: &str) -> bool {
    if pattern.starts_with(".*") {
        let suffix = &pattern[2..];
        text.ends_with(suffix)
    } else {
        text.ends_with(pattern)
    }
}

