            }
        }
        Ok(FieldSelector { ranges })
    }

    fn get_fields(&self, num_fields: usize) -> Vec<usize> {
        let mut fields = Vec::new();
        let mut seen = HashSet::new();

        for (start, end) in &self.ranges {
            let start_field = start.unwrap_or(1);
            let end_field = end.unwrap_or(num_fields);

            // Make sure we don't exceed the number of fields
            let actual_end = std::cmp::min(end_field, num_fields);

            if start_field <= num_fields {
                for field in start_field..=actual_end {
                    if !seen.contains(&field) {
                        fields.push(field);
                        seen.insert(field);
                    }
                }
            }
        }
        fields
    }
}

// Simple regex engine for basic patterns
fn matches_regex(pattern: &str, text: &str) -> bool {
    // Handle simple anchored patterns and literal matches
    if pattern == "\\s+" {
        // Special case for whitespace
        text.chars().all(|c| c.is_whitespace())
    } else if pattern.starts_with('^') && pattern.ends_with('$') {
        // Full match
        let inner = &pattern[1..pattern.len() - 1];
        regex_matches_full(inner, text)
    } else if pattern.starts_with('^') {
        let inner = &pattern[1..];
        regex_matches_prefix(inner, text)
    } else if pattern.ends_with('$') {
        let inner = &pattern[..pattern.len() - 1];
        regex_matches_suffix(inner, text)
    } else {
        // Contains
        text.contains(pattern)
    }
}

fn regex_matches_full(pattern: &str, text: &str) -> bool {
    if pattern.starts_with("is_") {
        text.starts_with("is_")
    } else if pattern == "[AC].*" {
        text.starts_with('A') || text.starts_with('C')
    } else if pattern == "[ac].*" {
        text.starts_with('a') || text.starts_with('c')
    } else if pattern == "[A-Z].*" {
        text.chars().next().map(|c| c.is_uppercase()).unwrap_or(false)
    } else {
        text == pattern
    }
}

fn regex_matches_prefix(pattern: &str, text: &str) -> bool {
    if pattern == "[AC].*" {
        text.starts_with('A') || text.starts_with('C')
    } else if pattern == "[ac].*" {
        text.starts_with('a') || text.starts_with('c')
    } else if pattern == "is_.*" {
        text.starts_with("is_")
    } else if pattern.ends_with(".*") {
        let prefix = &pattern[..pattern.len() - 2];
        text.starts_with(prefix)
    } else {
        text.starts_with(pattern)
    }
}

fn regex_matches_suffix(pattern: &str, text: &str) -> bool {
    if pattern.starts_with(".*") {
        let suffix = &pattern[2..];
        text.ends_with(suffix)
    } else {
        text.ends_with(pattern)
    }
}

fn split_on_whitespace(line: &str) -> Vec<String> {
    line.split_whitespace().map(|s| s.to_string()).collect()
}

fn split_line(line: &str, delimiter: &str, is_literal: bool) -> Vec<String> {
    if is_literal {
        line.split(delimiter).map(|s| s.to_string()).collect()
    } else if delimiter == "\\s+" {
        split_on_whitespace(line)
    } else {
        // Try to use it as a regex pattern
        // For now, just split on the literal string if it's not whitespace
        if delimiter.contains('[') || delimiter.contains('*') || delimiter.contains('+') {
            // Complex regex - for now just use as literal
            line.split(delimiter).map(|s| s.to_string()).collect()
        } else {
            line.split(delimiter).map(|s| s.to_string()).collect()
        }
    }
}

struct Args {
    input_files: Vec<PathBuf>,
    output_file: Option<PathBuf>,
    delimiter: String,
    delim_is_literal: bool,
    use_input_delim: bool,
    output_delimiter: String,
    fields: Option<String>,
    exclude: Option<String>,
    exclude_headers: Vec<String>,
    header_fields: Vec<String>,
    header_is_regex: bool,
}

fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut input_files = Vec::new();
    let mut output_file = None;
    let mut delimiter = "\\s+".to_string();
    let mut delim_is_literal = false;
    let mut use_input_delim = false;
    let mut output_delimiter = "\t".to_string();
    let mut fields = None;
    let mut exclude = None;
    let mut exclude_headers = Vec::new();
    let mut header_fields = Vec::new();
    let mut header_is_regex = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "--version" || arg == "-V" {
            println!("hck git:23bebe8-modified");
            std::process::exit(0);
        } else if arg == "-h" || arg == "--help" {
            print_help();
            std::process::exit(0);
        } else if arg == "-d" || arg == "--delimiter" {
            i += 1;
            if i < args.len() {
                delimiter = args[i].clone();
            } else {
                return Err("Error: -d requires a value".to_string());
            }
        } else if arg == "-L" || arg == "--delim-is-literal" {
            delim_is_literal = true;
        } else if arg == "-I" || arg == "--use-input-delim" {
            use_input_delim = true;
        } else if arg == "-D" || arg == "--output-delimiter" {
            i += 1;
            if i < args.len() {
                output_delimiter = args[i].clone();
            } else {
                return Err("Error: -D requires a value".to_string());
            }
        } else if arg == "-f" || arg == "--fields" {
            i += 1;
            if i < args.len() {
                fields = Some(args[i].clone());
            } else {
                return Err("Error: -f requires a value".to_string());
            }
        } else if arg == "-e" || arg == "--exclude" {
            i += 1;
            if i < args.len() {
                exclude = Some(args[i].clone());
            } else {
                return Err("Error: -e requires a value".to_string());
            }
        } else if arg == "-E" || arg == "--exclude-header" {
            i += 1;
            if i < args.len() {
                exclude_headers.push(args[i].clone());
            } else {
                return Err("Error: -E requires a value".to_string());
            }
        } else if arg == "-F" || arg == "--header-field" {
            i += 1;
            if i < args.len() {
                header_fields.push(args[i].clone());
            } else {
                return Err("Error: -F requires a value".to_string());
            }
        } else if arg == "-r" || arg == "--header-is-regex" {
            header_is_regex = true;
        } else if arg == "-o" || arg == "--output" {
            i += 1;
            if i < args.len() {
                output_file = Some(PathBuf::from(&args[i]));
            } else {
                return Err("Error: -o requires a value".to_string());
            }
        } else if arg.starts_with('-') && arg.len() > 1 && !arg.starts_with("--") {
            // Handle combined short options like -d: -f1
            let mut j = 1;
            while j < arg.len() {
                let c = arg.chars().nth(j).unwrap();
                match c {
                    'd' => {
                        // -d can be combined with value like -d:
                        if j + 1 < arg.len() {
                            delimiter = arg[j + 1..].to_string();
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                delimiter = args[i].clone();
                            } else {
                                return Err("Error: -d requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'L' => {
                        delim_is_literal = true;
                        j += 1;
                    }
                    'I' => {
                        use_input_delim = true;
                        j += 1;
                    }
                    'D' => {
                        if j + 1 < arg.len() {
                            output_delimiter = arg[j + 1..].to_string();
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                output_delimiter = args[i].clone();
                            } else {
                                return Err("Error: -D requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'f' => {
                        if j + 1 < arg.len() {
                            fields = Some(arg[j + 1..].to_string());
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                fields = Some(args[i].clone());
                            } else {
                                return Err("Error: -f requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'e' => {
                        if j + 1 < arg.len() {
                            exclude = Some(arg[j + 1..].to_string());
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                exclude = Some(args[i].clone());
                            } else {
                                return Err("Error: -e requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'E' => {
                        if j + 1 < arg.len() {
                            exclude_headers.push(arg[j + 1..].to_string());
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                exclude_headers.push(args[i].clone());
                            } else {
                                return Err("Error: -E requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'F' => {
                        if j + 1 < arg.len() {
                            header_fields.push(arg[j + 1..].to_string());
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                header_fields.push(args[i].clone());
                            } else {
                                return Err("Error: -F requires a value".to_string());
                            }
                            break;
                        }
                    }
                    'r' => {
                        header_is_regex = true;
                        j += 1;
                    }
                    'o' => {
                        if j + 1 < arg.len() {
                            output_file = Some(PathBuf::from(&arg[j + 1..]));
                            break;
                        } else {
                            i += 1;
                            if i < args.len() {
                                output_file = Some(PathBuf::from(&args[i]));
                            } else {
                                return Err("Error: -o requires a value".to_string());
                            }
                            break;
                        }
                    }
                    _ => {
                        return Err(format!("Unknown option: -{}", c));
                    }
                }
            }
        } else if arg.starts_with('-') {
            return Err(format!("Unknown option: {}", arg));
        } else {
            input_files.push(PathBuf::from(arg));
        }
        i += 1;
    }

    Ok(Args {
        input_files,
        output_file,
        delimiter,
        delim_is_literal,
        use_input_delim,
        output_delimiter,
        fields,
        exclude,
        exclude_headers,
        header_fields,
        header_is_regex,
    })
}

fn main() {
    let args_raw: Vec<String> = env::args().collect();

    let args = match parse_args(&args_raw) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    // Determine output delimiter
    let final_output_delim = if args.use_input_delim && args.delim_is_literal && args.output_delimiter == "\t" {
        args.delimiter.clone()
    } else {
        args.output_delimiter.clone()
    };

    // Prepare output
    let mut output: Box<dyn Write> = if let Some(path) = args.output_file {
        match File::create(path) {
            Ok(f) => Box::new(f),
            Err(e) => {
                eprintln!("Error opening output file: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        Box::new(io::stdout())
    };

    // Prepare input readers
    let readers: Vec<Box<dyn BufRead>> = if args.input_files.is_empty() {
        vec![Box::new(BufReader::new(io::stdin()))]
    } else {
        args.input_files
            .iter()
            .filter_map(|p| {
                match File::open(p) {
                    Ok(f) => Some(Box::new(BufReader::new(f)) as Box<dyn BufRead>),
                    Err(e) => {
                        eprintln!("Error opening file {:?}: {}", p, e);
                        None
                    }
                }
            })
            .collect()
    };

    // Process input
    for reader in readers {
        let mut is_first_line = true;
        let mut selected_header_fields: Option<Vec<usize>> = None;

        for line in reader.lines() {
            match line {
                Ok(line) => {
                    if is_first_line && (!args.header_fields.is_empty() || !args.exclude_headers.is_empty()) {
                        // Process header line
                        let (indices, _header_output) = process_headers(
                            &line,
                            &args.delimiter,
                            args.delim_is_literal,
                            &args.header_fields,
                            &args.exclude_headers,
                            args.header_is_regex,
                        );
                        selected_header_fields = Some(indices.clone());

                        // Output the header
                        let parts = split_line(&line, &args.delimiter, args.delim_is_literal);
                        let header_output: Vec<String> = indices
                            .iter()
                            .filter_map(|&idx| {
                                if idx > 0 && idx <= parts.len() {
                                    Some(parts[idx - 1].clone())
                                } else {
                                    None
                                }
                            })
                            .collect();
                        let _ = writeln!(output, "{}", header_output.join("\t"));
                        is_first_line = false;
                    } else if is_first_line {
                        is_first_line = false;
                        let parts = split_line(&line, &args.delimiter, args.delim_is_literal);

                        // Parse field selectors now that we know the number of fields
                        let mut field_selector: Option<Vec<usize>> = None;
                        let mut exclude_fields: Option<Vec<usize>> = None;

                        if let Some(f) = &args.fields {
                            match FieldSelector::parse(f) {
                                Ok(selector) => {
                                    field_selector = Some(selector.get_fields(parts.len()));
                                }
                                Err(e) => {
                                    eprintln!("Error parsing fields: {}", e);
                                    std::process::exit(1);
                                }
                            }
                        }

                        if let Some(e) = &args.exclude {
                            match FieldSelector::parse(e) {
                                Ok(selector) => {
                                    exclude_fields = Some(selector.get_fields(parts.len()));
                                }
                                Err(e) => {
                                    eprintln!("Error parsing exclude: {}", e);
                                    std::process::exit(1);
                                }
                            }
                        }

                        // Output first line
                        if let Some(ref selector) = field_selector {
                            let result: Vec<String> = selector
                                .iter()
                                .filter_map(|&idx| {
                                    if idx > 0 && idx <= parts.len() {
                                        Some(parts[idx - 1].clone())
                                    } else {
                                        None
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        } else {
                            // No field selector, use exclude only
                            let result: Vec<String> = parts
                                .into_iter()
                                .enumerate()
                                .filter_map(|(i, part)| {
                                    if let Some(ref exc) = exclude_fields {
                                        if !exc.contains(&(i + 1)) {
                                            Some(part)
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(part)
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        }
                    } else {
                        // Process data lines
                        let parts = split_line(&line, &args.delimiter, args.delim_is_literal);

                        // Parse field selectors once with first data line's field count
                        let mut field_selector: Option<Vec<usize>> = None;
                        let mut exclude_fields: Option<Vec<usize>> = None;

                        if let Some(f) = &args.fields {
                            match FieldSelector::parse(f) {
                                Ok(selector) => {
                                    field_selector = Some(selector.get_fields(parts.len()));
                                }
                                Err(e) => {
                                    eprintln!("Error parsing fields: {}", e);
                                    std::process::exit(1);
                                }
                            }
                        }

                        if let Some(e) = &args.exclude {
                            match FieldSelector::parse(e) {
                                Ok(selector) => {
                                    exclude_fields = Some(selector.get_fields(parts.len()));
                                }
                                Err(e) => {
                                    eprintln!("Error parsing exclude: {}", e);
                                    std::process::exit(1);
                                }
                            }
                        }

                        if let Some(ref selected_indices) = selected_header_fields {
                            let result: Vec<String> = selected_indices
                                .iter()
                                .filter_map(|&idx| {
                                    if idx > 0 && idx <= parts.len() {
                                        Some(parts[idx - 1].clone())
                                    } else {
                                        None
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join("\t"));
                        } else if let Some(ref selector) = field_selector {
                            let result: Vec<String> = selector
                                .iter()
                                .filter_map(|&idx| {
                                    if idx > 0 && idx <= parts.len() {
                                        Some(parts[idx - 1].clone())
                                    } else {
                                        None
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        } else {
                            let result: Vec<String> = parts
                                .into_iter()
                                .enumerate()
                                .filter_map(|(i, part)| {
                                    if let Some(ref exc) = exclude_fields {
                                        if !exc.contains(&(i + 1)) {
                                            Some(part)
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(part)
                                    }
                                })
                                .collect();
                            let _ = writeln!(output, "{}", result.join(&final_output_delim));
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error reading line: {}", e);
                }
            }
        }
    }
}

fn process_headers(
    header_line: &str,
    input_delim: &str,
    is_literal: bool,
    header_fields: &[String],
    exclude_headers: &[String],
    header_is_regex: bool,
) -> (Vec<usize>, String) {
    let parts = split_line(header_line, input_delim, is_literal);
    let num_parts = parts.len();

    let mut selected_indices: Vec<usize> = Vec::new();

    if !header_fields.is_empty() {
        // When using header fields, include only matching headers
        for header_spec in header_fields {
            if header_is_regex {
                for (i, part) in parts.iter().enumerate() {
                    if matches_regex(header_spec, part) && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            } else {
                for (i, part) in parts.iter().enumerate() {
                    if part == header_spec && !selected_indices.contains(&(i + 1)) {
                        selected_indices.push(i + 1);
                    }
                }
            }
        }
    } else {
        // No header fields specified, include all except excluded ones
        selected_indices = (1..=num_parts).collect();
    }

    // Apply exclude filters
    for exclude_spec in exclude_headers {
        if header_is_regex {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    !matches_regex(exclude_spec, &parts[idx - 1])
                } else {
                    true
                }
            });
        } else {
            selected_indices.retain(|&idx| {
                if idx > 0 && idx <= num_parts {
                    &parts[idx - 1] != exclude_spec
                } else {
                    true
                }
            });
        }
    }

    let result: Vec<String> = selected_indices
        .iter()
        .filter_map(|&idx| {
            if idx > 0 && idx <= num_parts {
                Some(parts[idx - 1].clone())
            } else {
                None
            }
        })
        .collect();

    (selected_indices, result.join("\t"))
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [INPUT]...");
    println!();
    println!("Arguments:");
    println!("  [INPUT]...  Input files to parse, defaults to stdin.");
    println!();
    println!("Options:");
    println!("  -o, --output <OUTPUT>              Output file to write to");
    println!("  -d, --delimiter <DELIMITER>        Delimiter to use on input files");
    println!("  -L, --delim-is-literal             Treat the delimiter as a string literal");
    println!("  -I, --use-input-delim              Use the input delimiter as the output delimiter");
    println!("  -D, --output-delimiter <DELIM>     Delimiter string to use on outputs");
    println!("  -f, --fields <FIELDS>              Fields to keep in the output");
    println!("  -e, --exclude <EXCLUDE>            Fields to exclude from the output");
    println!("  -E, --exclude-header <EXCLUDE>     Headers to exclude from the output");
    println!("  -F, --header-field <HEADER>        A string literal or regex to select headers");
    println!("  -r, --header-is-regex              Treat the header_fields as regexs");
    println!("  -h, --help                         Print help");
    println!("  -V, --version                      Print version");
}
